from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
REAL=ROOT/'app/src/main/java/com/mg/fixturecockpitsim/visual/RealisticFighterMesh.java'
CTRL=ROOT/'app/src/main/java/com/mg/fixturecockpitsim/visual/AircraftControlSurfaces.java'
MECH=ROOT/'app/src/main/java/com/mg/fixturecockpitsim/visual/MechanicalDynamicsOverlay.java'
JET=ROOT/'app/src/main/java/com/mg/fixturecockpitsim/Jet3DView.java'


def rep(text, old, new, label):
    if new in text:
        return text
    if old not in text:
        raise SystemExit(f'v88 wing patch anchor missing: {label}')
    return text.replace(old, new, 1)

