m=MECH.read_text()
m=rep(m,
'''            NOZZLE_PETAL=21f, HEAT_SHIELD=28f, PYLON=30f;\n''',
'''            NOZZLE_PETAL=21f, HEAT_SHIELD=28f, DETAIL=29f, PYLON=30f,\n            LE_FLAP_L=50f, LE_FLAP_R=51f;\n''','LE mechanical ids')
m=rep(m,
'''        b.controlSurfaceMechanics();\n        b.nozzleMechanics();\n''',
'''        b.controlSurfaceMechanics();\n        b.leadingEdgeFlapMechanics();\n        b.nozzleMechanics();\n''','LE mechanical build')
anchor='''    /** 12-13: synchronising rings, petal jacks and spherical pivots. */\n    private void nozzleMechanics(){\n'''
method='''    /** Leading-edge hinge barrels, crank arms and moving actuator brackets. */\n    private void leadingEdgeFlapMechanics(){\n        for(float side:new float[]{-1f,1f}){\n            float[] xs={1.05f,1.78f,2.58f,3.40f,4.18f,4.70f};\n            float[] ys={.365f,.325f,.278f,.230f,.195f,.168f};\n            float[] zs={-2.12f,-1.73f,-1.28f,-.83f,-.43f,-.19f};\n            part=DETAIL;\n            for(int i=0;i<xs.length-1;i++)\n                cylinderBetween(xs[i]*side,ys[i],zs[i],xs[i+1]*side,ys[i+1],zs[i+1],.018f,9);\n            part=side<0f?LE_FLAP_L:LE_FLAP_R;\n            for(int i=1;i<xs.length-1;i++){\n                float x=xs[i]*side,y=ys[i],z=zs[i];\n                ellipsoid(x,y,z,.034f,.026f,.038f,9,6);\n                cylinderBetween(x,y,z,x,y-.080f,z-.115f,.013f,8);\n                cylinderBetween(x,y-.080f,z-.115f,x+.095f*side,y-.105f,z-.155f,.010f,7);\n            }\n        }\n    }\n\n'''
m=rep(m,anchor,method+anchor,'LE hinge mechanics method')
MECH.write_text(m)

